// AuthServiceClient is the client API for AuthService service.
//
// For semantics around ctx use and closing/ending streaming RPCs, please refer to https://pkg.go.dev/google.golang.org/grpc/?tab=doc#ClientConn.NewStream.
//
// AuthService — separado de UserService porque los endpoints de auth
// suelen tener políticas distintas (ej. SkipFunc en el interceptor JWT,
// rate-limits específicos, sin Authorization header en Login).
type AuthServiceClient interface {
	// Authenticate verifica credenciales sin emitir tokens. Útil para
	// integraciones internas que validan permisos sin necesidad de JWT.
	Authenticate(ctx context.Context, in *AuthenticateRequest, opts ...grpc.CallOption) (*AuthenticateResponse, error)
	// Login emite un par access+refresh JWT.
	Login(ctx context.Context, in *LoginRequest, opts ...grpc.CallOption) (*LoginResponse, error)
	// Refresh rota el refresh token (revoca el viejo, emite uno nuevo).
	Refresh(ctx context.Context, in *RefreshRequest, opts ...grpc.CallOption) (*RefreshResponse, error)
	// Logout revoca el refresh token. El access sigue siendo válido hasta
	// su exp natural — el cliente debe descartarlo.
	Logout(ctx context.Context, in *LogoutRequest, opts ...grpc.CallOption) (*EmptyResponse, error)
	// RequestStudentOTP genera un OTP de 6 dígitos y lo envía al email
	// del estudiante vía hubspot_service. Silencioso si email no existe
	// o user no es estudiante (anti enumeration). Público.
	RequestStudentOTP(ctx context.Context, in *RequestStudentOTPRequest, opts ...grpc.CallOption) (*EmptyResponse, error)
	// VerifyStudentOTP valida el código y emite par access+refresh JWT.
	// Público.
	VerifyStudentOTP(ctx context.Context, in *VerifyStudentOTPRequest, opts ...grpc.CallOption) (*LoginResponse, error)
	// RegisterStudentWithKey crea (o reusa) un usuario estudiante asociado
	// al colegio de una key valida y dispara el envio del OTP. Endpoint
	// publico (sin JWT): el control de acceso es la propia validez de la
	// key. El gateway ya valido el key_code antes de invocarlo y resolvio
	// el school_id correspondiente.
	//
	// Si el email ya existe como estudiante del mismo colegio, no crea
	// nada — solo reenvia OTP. Si existe pero pertenece a otro rol u otro
	// colegio, devuelve error.
	RegisterStudentWithKey(ctx context.Context, in *RegisterStudentWithKeyRequest, opts ...grpc.CallOption) (*RegisterStudentWithKeyResponse, error)
	// CheckStudentEmail responde si un email existe como estudiante. Lo
	// invoca el gateway tras validar un key_code (no es expuesto crudo —
	// el front llama a /api/auth/student/lookup-by-key que primero pasa
	// por keys_service.ValidateKey). Permite que la pantalla de acceso
	// decida automaticamente entre flujo "ingresar con OTP" (existe) vs
	// "registrar con llave" (no existe), sin obligar al alumno a saber
	// cual le toca. Anti-enumeracion: solo responde si quien pregunta ya
	// posee un key_code valido.
	CheckStudentEmail(ctx context.Context, in *CheckStudentEmailRequest, opts ...grpc.CallOption) (*CheckStudentEmailResponse, error)
}

